const TRANE_YEAR_LETTER = { W:1983,X:1984,Y:1985,Z:1986,B:1987,C:1988,D:1989,E:1990,F:1991,G:1992,H:1993,J:1994,K:1995,L:1996,M:1997,N:1998,P:1999,R:2000,S:2001 };
